/// <summary>
/// Validation class for inbound file share incl sub directories
/// </summary>
class OMGAzureValidator_InboundFileShareSubDir extends OMGAzureValidator_InboundFileShare
{
}

Method.Source:
/// <summary>
/// Validates the archiving
/// </summary>
/// <returns>True if all ok</returns>
protected boolean validateArchiving()
{
    OMGInboundDataContract_AzureFileShareSubDir dataContract    = dataContract_Azure;
    boolean                                     ret = true;
    ;

    if (dataContract.parmArchiveUnderSourceDirectory() == NoYes::No)
    {
        ret = super();
    }
    else
    {
        if (!dataContract.parmArchiveFolderName())
        {
            ret = checkFailed("@OMG:ArchiveNameMissing");
        }
    }
    return ret;
}
